import{_ as t,o as r,c as s,a1 as a}from"./chunks/framework.DdbKPUhY.js";const g=JSON.parse('{"title":"Request API Spec","description":"","frontmatter":{},"headers":[],"relativePath":"spec/request-api.md","filePath":"spec/request-api.md"}'),o={name:"spec/request-api.md"};function i(n,e,u,l,d,h){return r(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="request-api-spec" tabindex="-1">Request API Spec <a class="header-anchor" href="#request-api-spec" aria-label="Permalink to &quot;Request API Spec&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The Request module parses incoming HTTP requests using llhttp, provides access to request method, path, headers, query parameters, and body.</p><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><h3 id="uvhttp-request-init" tabindex="-1">uvhttp_request_init <a class="header-anchor" href="#uvhttp-request-init" aria-label="Permalink to &quot;uvhttp_request_init&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>uvhttp_error_t uvhttp_request_init(uvhttp_request_t* request, uv_tcp_t* client)</code></li><li><strong>Purpose</strong>: Initialize a request object for a client connection</li><li><strong>Preconditions</strong>: <code>request</code> must be a valid pointer to uninitialized memory. <code>client</code> must be a valid TCP handle.</li><li><strong>Postconditions</strong>: Request is initialized with empty state, ready for parsing.</li><li><strong>Error conditions</strong>: <ul><li><code>UVHTTP_ERROR_INVALID_PARAM</code>: request or client is NULL</li></ul></li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-request-cleanup" tabindex="-1">uvhttp_request_cleanup <a class="header-anchor" href="#uvhttp-request-cleanup" aria-label="Permalink to &quot;uvhttp_request_cleanup&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_request_cleanup(uvhttp_request_t* request)</code></li><li><strong>Purpose</strong>: Free request resources (body, headers)</li><li><strong>Preconditions</strong>: <code>request</code> must be valid.</li><li><strong>Postconditions</strong>: All allocated fields are freed. Pointers are NULLed.</li><li><strong>Thread safety</strong>: Not thread-safe.</li></ul><h3 id="uvhttp-request-get-method" tabindex="-1">uvhttp_request_get_method <a class="header-anchor" href="#uvhttp-request-get-method" aria-label="Permalink to &quot;uvhttp_request_get_method&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>const char* uvhttp_request_get_method(const uvhttp_request_t* request)</code></li><li><strong>Purpose</strong>: Get the HTTP method string</li><li><strong>Preconditions</strong>: <code>request</code> must be valid.</li><li><strong>Returns</strong>: Method string (e.g., &quot;GET&quot;, &quot;POST&quot;), or NULL if not yet parsed.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-request-get-path" tabindex="-1">uvhttp_request_get_path <a class="header-anchor" href="#uvhttp-request-get-path" aria-label="Permalink to &quot;uvhttp_request_get_path&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>const char* uvhttp_request_get_path(const uvhttp_request_t* request)</code></li><li><strong>Purpose</strong>: Get the request path</li><li><strong>Preconditions</strong>: <code>request</code> must be valid.</li><li><strong>Returns</strong>: Path string (e.g., &quot;/api/users&quot;), or NULL if not yet parsed.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-request-get-header" tabindex="-1">uvhttp_request_get_header <a class="header-anchor" href="#uvhttp-request-get-header" aria-label="Permalink to &quot;uvhttp_request_get_header&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>const char* uvhttp_request_get_header(const uvhttp_request_t* request, const char* name)</code></li><li><strong>Purpose</strong>: Get a specific header value</li><li><strong>Preconditions</strong>: <code>request</code> must be valid. <code>name</code> must be non-NULL.</li><li><strong>Returns</strong>: Header value string, or NULL if not found.</li><li><strong>Error conditions</strong>: Returns NULL if request or name is NULL.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-request-get-query-param" tabindex="-1">uvhttp_request_get_query_param <a class="header-anchor" href="#uvhttp-request-get-query-param" aria-label="Permalink to &quot;uvhttp_request_get_query_param&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>const char* uvhttp_request_get_query_param(const uvhttp_request_t* request, const char* name)</code></li><li><strong>Purpose</strong>: Get a specific query parameter value</li><li><strong>Preconditions</strong>: <code>request</code> must be valid. <code>name</code> must be non-NULL.</li><li><strong>Returns</strong>: Parameter value string, or NULL if not found.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-request-get-body" tabindex="-1">uvhttp_request_get_body <a class="header-anchor" href="#uvhttp-request-get-body" aria-label="Permalink to &quot;uvhttp_request_get_body&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>const char* uvhttp_request_get_body(const uvhttp_request_t* request)</code></li><li><strong>Purpose</strong>: Get the request body</li><li><strong>Preconditions</strong>: <code>request</code> must be valid.</li><li><strong>Returns</strong>: Body pointer, or NULL if empty.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-request-get-body-length" tabindex="-1">uvhttp_request_get_body_length <a class="header-anchor" href="#uvhttp-request-get-body-length" aria-label="Permalink to &quot;uvhttp_request_get_body_length&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>size_t uvhttp_request_get_body_length(const uvhttp_request_t* request)</code></li><li><strong>Purpose</strong>: Get the request body length</li><li><strong>Preconditions</strong>: <code>request</code> must be valid.</li><li><strong>Returns</strong>: Body length in bytes.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-request-get-client-ip" tabindex="-1">uvhttp_request_get_client_ip <a class="header-anchor" href="#uvhttp-request-get-client-ip" aria-label="Permalink to &quot;uvhttp_request_get_client_ip&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>const char* uvhttp_request_get_client_ip(const uvhttp_request_t* request)</code></li><li><strong>Purpose</strong>: Get the client IP address</li><li><strong>Preconditions</strong>: <code>request</code> must be valid.</li><li><strong>Returns</strong>: IP address string.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h3 id="uvhttp-request-foreach-header" tabindex="-1">uvhttp_request_foreach_header <a class="header-anchor" href="#uvhttp-request-foreach-header" aria-label="Permalink to &quot;uvhttp_request_foreach_header&quot;">​</a></h3><ul><li><strong>Signature</strong>: <code>void uvhttp_request_foreach_header(const uvhttp_request_t* request, void (*callback)(const char* name, const char* value, void* user_data), void* user_data)</code></li><li><strong>Purpose</strong>: Iterate over all request headers</li><li><strong>Preconditions</strong>: <code>request</code> must be valid. <code>callback</code> must be non-NULL.</li><li><strong>Thread safety</strong>: Thread-safe for reads.</li></ul><h2 id="behavior-rules" tabindex="-1">Behavior Rules <a class="header-anchor" href="#behavior-rules" aria-label="Permalink to &quot;Behavior Rules&quot;">​</a></h2><ol><li><p><strong>Parsing</strong>: HTTP parsing is done via llhttp callbacks. The request object is populated incrementally as data arrives.</p></li><li><p><strong>Header limits</strong>: Maximum header count is <code>UVHTTP_MAX_HEADERS</code> (64). Maximum header name length is 256 bytes. Maximum header value length is 4096 bytes.</p></li><li><p><strong>URL limits</strong>: Maximum URL length is 2048 bytes. Path traversal (<code>../</code>) is checked and rejected.</p></li><li><p><strong>Body limits</strong>: Maximum body size is configurable (default 10 MB). Larger bodies are rejected.</p></li><li><p><strong>Query parsing</strong>: Query parameters are parsed from the URL. Parameter names and values are validated for dangerous characters.</p></li><li><p><strong>Header validation</strong>: Header names must be alphanumeric with hyphens. Header values are checked for control characters.</p></li></ol><h2 id="test-requirements" tabindex="-1">Test Requirements <a class="header-anchor" href="#test-requirements" aria-label="Permalink to &quot;Test Requirements&quot;">​</a></h2><ul><li>Method, path, header access</li><li>Query parameter extraction</li><li>Body access</li><li>NULL parameter handling for all accessors</li><li>Header iteration</li><li>URL validation (path traversal rejection)</li><li>Maximum limits enforcement</li><li>Empty request handling</li></ul>',28)])])}const p=t(o,[["render",i]]);export{g as __pageData,p as default};
